macro.command:
//Last Updated: 9/14/2023
//Author: EskieMoh#2969

//Set torch or lantern
let lightSource = "torch"

if (lightSource == "torch"){
file = "https://i.imgur.com/1U1eb9t.png"
}  
else if (lightSource == "lantern"){
file = "https://i.imgur.com/3wFQD02.png"
}

let lightDim = token.document.light.dim;
let lightBright = token.document.light.bright;

if (lightDim == 0 && lightBright == 0){
new Sequence()

.effect()
.delay(150)
.name(`${token.document.name} ${lightSource}`)
.file("jb2a.impact.002.orange")
.atLocation(token)
.attachTo(token, {followRotation: true, local: true})
.scaleToObject(0.9, {considerTokenScale: true})
.spriteOffset({x:0.525*token.document.width, y:-0.05*token.document.width}, {gridUnits:true})
.spriteRotation(45)
.zIndex(0.1)
.playIf(() => {
return lightSource == "torch";
})

.effect()
.name(`${token.document.name} ${lightSource}`)
.file(file)
.atLocation(token)
.attachTo(token, {followRotation: true, local: true})
.scaleToObject(1.2, {considerTokenScale: true})
.scaleIn(0, 500, {ease: "easeOutElastic"})
.scaleOut(0, 250, {ease: "easeOutCubic"})
.spriteOffset({x:0.35*token.document.width, y:0.1*token.document.width}, {gridUnits:true})
.animateProperty("sprite", "rotation", { from: 15, to: -15, duration: 300, ease: "easeInOutBack"})
.animateProperty("sprite", "rotation", { from: 0, to: 30, duration: 250, delay: 200, ease: "easeOutBack"})
.persist()
.zeroSpriteRotation()
.playIf(() => {
return lightSource == "torch";
})

.effect()
.delay(250)
.name(`${token.document.name} ${lightSource}`)
.file("jb2a.flames.01.orange")
.atLocation(token)
.attachTo(token, {followRotation: true, local: true})
.scaleToObject(1, {considerTokenScale: true})
.spriteOffset({x:0.5*token.document.width, y:-0.05*token.document.width}, {gridUnits:true})
.persist()
.spriteRotation(45)
.zIndex(0.1)
.waitUntilFinished(-500)
.playIf(() => {
return lightSource == "torch";
})

.effect()
.name(`${token.document.name} ${lightSource}`)
.file(file)
.atLocation(token)
.attachTo(token, {followRotation: true, local: true})
.scaleToObject(1, {considerTokenScale: true})
.scaleIn(0, 500, {ease: "easeOutElastic"})
.scaleOut(0, 250, {ease: "easeOutCubic"})
.spriteOffset({x:0.35*token.document.width, y:0.1*token.document.width}, {gridUnits:true})
.animateProperty("sprite", "rotation", { from: 15, to: -15, duration: 300, ease: "easeInOutBack"})
.animateProperty("sprite", "rotation", { from: 0, to: 30, duration: 250, delay: 200, ease: "easeOutBack"})
.loopProperty("sprite", "rotation", { from: 3, to: -3, duration: 1500, ease: "easeOutQuad", pingPong: true })
.persist()
.zeroSpriteRotation()
.waitUntilFinished(-500)
.playIf(() => {
return lightSource == "lantern";
})

.thenDo(function(){
var light = {dim: 0, bright: 0};
token.document.update({light});

Sequencer.EffectManager.endEffects({ name: `${token.document.name} ${lightSource}`, object: token });
})

.play()

//Define token light options
var light = {dim: 30, bright: 15, alpha:0.25, luminosity: 0.5, color: "#ffb433", animation: {type: "torch", speed: 4, intensity: 4},attenuation: 0.75, contrast:0.15, shadows:0.2,};

await token.document.update({light});

} else {

await Sequencer.EffectManager.endEffects({ name: `${token.document.name} ${lightSource}`, object: token });

var light = {dim: 0, bright: 0};
await token.document.update({light});
}

let dialog = await new Dialog({
  title: "Identify",
  content: `
    <p>Would you like to identify an item? (Drag it to the box below!)</p>
    <form>
      <div class="form-group">
        <div class="form-fields">
          <input type="text" placeholder="Drag item here..." id="identify" readonly>
          <div style="width: 50px; height: 50px; display: inline-block;">
            <img id="itemImage" src="" alt="Item Image" style="max-width: 100%; max-height: 100%; display: none;">
          </div>
          <span id="itemName" style="margin-left: 10px;"></span>
        </div>
      </div>
    </form>`,
  buttons: {
    identify: {
      label: "Identify",
      callback: async (html) => {
        const itemUuid = html[0].querySelector("#identify").value;
        const ForienIdentification = game.modules.get('forien-unidentified-items');
        const ArchonIdentification = game.modules.get('archon');
        const findItem = await fromUuid(itemUuid);
        const findItemQuantity = findItem?.system?.quantity;

		// Check if the item exists
        if (!findItem) {
          ui.notifications.error("Item not found");
          return;
        }

	// Identify the item using available modules based on item flags
        let identified = false;

		// Check if the ForienIdentification module is installed, active, and no "archon.uuid" flag present
        if (ForienIdentification && ForienIdentification.active && !findItem?.flags?.archon?.uuid) {
          identified = await ForienIdentification.api.identify(findItem);
          if (identified) {
            handleIdentificationSuccess(itemUuid, findItemQuantity);
            return;
          }
        }

		// Check if the ArchonIdentification module is installed, active, and no "forien-unidentified-items" flag present
        if (ArchonIdentification && ArchonIdentification.active && !findItem?.flags?.["forien-unidentified-items"]?.origData && !identified) {
          identified = await ArchonIdentification.Archon.reveal(findItem);
          if (identified) {
            handleIdentificationSuccess(itemUuid, findItemQuantity);
            return;
          }
        }
		// No active module found to identify the item
        ui.notifications.error("No active module found to identify the item");
      }
    },
    cancel: {
      label: "Cancel",
      callback: () => false
    }
  },
  default: "Cancel",
 render: (html) => {
  const inputField = html.find("#identify")[0];
  const itemImage = html.find("#itemImage")[0];
  const itemNameSpan = html.find("#itemName")[0];
  const isFirefox = navigator.userAgent.toLowerCase().indexOf('firefox') > -1;

  // Event listener for drop
  const handleDrop = async (e) => {
	e.preventDefault();
	const data = JSON.parse(e.dataTransfer.getData("text/plain"));
	if (data.type !== "Item") return;
	inputField.value = data.uuid;

	const item = await fromUuid(data.uuid);
	if (item && item.img) {
	  itemImage.src = item.img;
	  itemImage.style.display = "block";
	  itemImage.style.margin = "auto";
	  itemImage.style.display = "block";
	  itemImage.style.maxWidth = "100%";
	  inputField.style.display = "none";
	  itemNameSpan.textContent = item.name;
	}
  };

  if (isFirefox) {
	inputField.addEventListener('dragover', (e) => {
	  e.preventDefault();
	});

	inputField.addEventListener('drop', handleDrop);
  } else {
	inputField.addEventListener("drop", handleDrop);
	}
 }
}).render(true);

async function handleIdentificationSuccess(itemUuid, findItemQuantity) {
  const findItemNew = await fromUuid(itemUuid);
  const findItemNewQuantity = findItemNew?.system?.quantity;

  // Update the item quantity if it changed during identification
  if (findItemQuantity !== findItemNewQuantity) {
    await findItemNew.update({ 'system.quantity': findItemQuantity });
  }

  const itemName = findItemNew.name;
  const itemQuantity = findItemNew.system.quantity || 1;
  const itemText = itemQuantity === 1 ? `${itemQuantity} <a class="open-item-sheet" data-item-id="${findItemNew.id}">${findItemNew.name}</a> item` : `${itemQuantity} <a class="open-item-sheet" data-item-id="${findItemNew.id}">${findItemNew.name}</a> items`;

  const content = `<p>You identified ${itemText}!</p>`;

  const dialogSuccess = new Dialog({
    title: "Identified",
    content: content,
    buttons: {
      okay: {
        label: "Okay"
      }
    },
    default: "okay",
    render: (html) => {
      html.find('.open-item-sheet').click((ev) => {
        findItemNew.sheet.render(true);
      });
    }
  });

  dialogSuccess.render(true);
}

if (args[0].macroPass === "postActiveEffects") {
    const items = actor.items.contents.filter(i => i.system.identified === false);
    if (items.length === 0) return ui.notifications.warn("You have no unidentified items");

    foundry.applications.api.DialogV2.wait({
        window: { title: "Identify Cast Type" },
        content: `<p>Would you like to cast Identify ritually?</p>`,
        buttons: [{
            action: "Yes",
            label: "Yes",
            callback: () => listUnidentifiedItems(true)
        },
        {
            action: "No",
            label: "No",
            default: true,
            callback: () => {
                const spells = actor.system.spells;
                let spellLevel = macroItem?.system?.level;
                let checkType = macroItem?.system?.preparation?.mode;
                let hasSpellSlots = false;
                if(checkType === "prepared" && macroItem?.system?.preparation?.prepared === false) return;
                if(checkType === "prepared" || checkType === "always")
                {
                    for (let level = spellLevel; level <= 9; level++) {
                        let spellSlot = actor.system.spells[`spell${level}`].value;
                        if (spellSlot > 0) {
                            hasSpellSlots = true;
                            break;
                        }
                    }
                }
                else if(checkType === "pact")
                {
                    let spellSlotValue = spells.pact.value;
                    if (spellSlotValue > 0) hasSpellSlots = true;
                }
                else if(checkType === "innate" || checkType === "atwill")
                {
                    let slotValue = macroItem.system.uses.value;
                    let slotEnabled = macroItem.system.uses.per;
                    if (slotValue > 0 || slotEnabled === null) hasSpellSlots = true;
                }

                if (!hasSpellSlots) {
                    return ui.notifications.warn("You have no spell slots available");
                }
                else {
                    listUnidentifiedItems(false)
                }
            }
        }],
        close: async (event, dialog) => {
            return;
        }, rejectClose:false
    });

    async function listUnidentifiedItems(ritual) {
        let dropdownOptions = "";
        const optionBackground = (document.body.classList.contains("theme-dark")) ? 'black' : 'var(--color-bg)';
        if (!ritual) {
            for (let level = 1; level <= 9; level++) {
                let spellSlot = actor.system.spells[`spell${level}`].value;
                if (spellSlot > 0) {
                    let levelWithOrdinal = getOrdinalNumber(level);
                    dropdownOptions += `<option class="gps-dialog-option" style="background-color: ${optionBackground};" value="${level}">${levelWithOrdinal} Level (${spellSlot})</option>`;
                }
            }
        }

        let timeToCast = ritual ? "(11m)" : "(1m)";
        let spellLevelDropdown = dropdownOptions ? `<select style="background-color: rgba(181, 99, 69, 0.2);" class="gps-dialog-select" id="spellLevelDropdown">${dropdownOptions}</select>` : '';

        let content = `
            <style>
                .dialog {
                    width: 550px !important;
                }
                .identify-btn:hover {
                    box-shadow: 0 0 8px #333; /* Stronger grey glow on hover */
                }
                .item-list {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    padding: 4px;
                    height: 50px; /* Ensure consistent height */
                }
                .item-list div {
                    flex-grow: 1;
                    display: flex;
                    align-items: center;
                }
                .item-list img {
                    border: 0;
                    margin-right: 10px;
                    vertical-align: middle; /* Ensure the image is aligned vertically */
                }
                .item-list span {
                    margin-left: 5px;
                }
            </style>
            <ul style='list-style-type: none; padding: 0;'>
        `;
        items.forEach((item) => {
            content += `
                <li id="item-${item.id}" class="item-list">
                    <div>
                        <img src="${item.img}" width="30" height="30">
                        <span>${item.name} (${item.system.quantity})</span>
                    </div>
                    <span id="spellLevelSelect_${item.id}">${spellLevelDropdown}</span>
                    <button type="button" class="identify-btn" data-item-id="${item.id}" style="width: 25%; margin-left: 10px;">Identify ${timeToCast}</button>
                </li>
            `;
        });
        content += "</ul>";

        foundry.applications.api.DialogV2.wait({
            window: { title: (ritual) ? "Identify Items Ritually" : "Identify Items" },
            content: content,
            buttons: [{
                action: "Close",
                label: "<i class='fas fa-times' style='margin-right: 5px;'></i>Close",
            }],
            render: (event) => {
                let dialogElement = event.target.element;
                dialogElement.querySelectorAll('.identify-btn').forEach(button => {
                    button.addEventListener('click', async event => {
                        const itemId = event.currentTarget.dataset.itemId;
                        const selectElement = dialogElement.querySelector(`#spellLevelSelect_${itemId} select`);
                        let castLevel = !ritual ? selectElement?.value : null;

                        if (castLevel) {
                            let currentSlots = actor.system.spells[`spell${castLevel}`].value;
                            await actor.update({ [`system.spells.spell${castLevel}.value`]: currentSlots - 1 });
                            refreshSpellLevelDropdown(dialogElement, actor);
                        }

                        await identifyItem(itemId, dialogElement);
                    });
                });
            },
            close: async (event, dialog) => {
                return;
            }, rejectClose:false
        });
    }

    async function identifyItem(itemId, dialogElement) {
        const itemData = actor.items.get(itemId);
        if (itemData) {
            if (MidiQOL.safeGetGameSetting('gambits-premades', 'Enable Identify Restrictions') === true) {
                await game.gps.socket.executeAsGM('gmIdentifyItem', { itemUuid: itemData.uuid });
            } else {
                await itemData.update({ "system.identified": true });
            }
            ui.notifications.info(`Identified: ${itemData.name}`);

            const itemText = `
                <div style="display: flex; align-items: center;">
                    <img src="${itemData.img}" width="30" height="30">
                    <span><a class="open-item-sheet" data-item-id="${itemData.id}">${itemData.name}</a> (${itemData.system.quantity})</span>
                </div>
            `;

            const listItem = dialogElement.querySelector(`#item-${itemId}`);
            listItem.innerHTML = itemText;
            listItem.querySelector('.open-item-sheet').addEventListener('click', (ev) => {
                itemData.sheet.render(true);
            });
        }
    }

    async function refreshSpellLevelDropdown(dialogElement, actor) {
        const items = actor.items.contents.filter(i => i.system.identified === false);
        const optionBackground = (document.body.classList.contains("theme-dark")) ? 'black' : 'var(--color-bg)';

        let dropdownOptions = '';
        for (let level = 1; level <= 9; level++) {
            let spellSlot = actor.system.spells[`spell${level}`]?.value;
            if (spellSlot > 0) {
                let levelWithOrdinal = getOrdinalNumber(level);
                dropdownOptions += `<option class="gps-dialog-option" style="background-color: ${optionBackground};" value="${level}">${levelWithOrdinal} Level (${spellSlot})</option>`;
            }
        }

        if (dropdownOptions) {
            items.forEach(i => {
                const selectContainer = dialogElement.querySelector(`#spellLevelSelect_${i.id}`);
                if (selectContainer) {
                    selectContainer.innerHTML = `<select style="background-color: rgba(181, 99, 69, 0.2);" class="gps-dialog-select" id="spellLevelDropdown">${dropdownOptions}</select>`;
                }
            });
        }
    }

    function getOrdinalNumber(number) {
        switch (number) {
            case 1: return "1st";
            case 2: return "2nd";
            case 3: return "3rd";
            default: return number + "th";
        }
    }
}

if (args[0].macroPass === "preItemRoll") {
    workflow.config.consumeSpellSlot = null;
    workflow.options.configureDialog = false;
}

const dim = 40;
const bright = 20;
const color = undefined; // game.user.color;
const alpha = "0.25";
const type = "torch";
const speed = 3;
const intensity = 1;
const angle = 360;

const lightOptions = {dim,bright,color,alpha,type,speed,intensity,angle};

if (!game.modules.get("warpgate")?.active) return ui.notifications.error("Please enable the Warp Gate module");
const mutName = "Cantrip: Light";

if (args[0].macroPass === "preActiveEffects") {
    const {failedSaves} = args[0];
    if (!actor || !token || !failedSaves) return ui.notifications.error("Light spell error - Do you have Item Macro Sheet hooks option enabled? If yes disable; Notify GM");
    let {dim,bright,color,alpha,type,speed,intensity,angle} = lightOptions ?? {};
    const previousTargetUuid = DAE.getFlag(actor, "lightSRD");
    const previousTokenDoc = previousTargetUuid ? fromUuidSync(previousTargetUuid) : undefined;
    const effect = previousTokenDoc ? getEffect(previousTokenDoc.actor,"Light") : undefined;
    if (previousTargetUuid && effect) await MidiQOL.socket().executeAsGM("removeEffects", {actorUuid: previousTargetUuid, effects:[effect.id]});
    if (previousTokenDoc && _hasMutation(previousTokenDoc,mutName)) await warpgate.revert(previousTokenDoc,mutName);
    await warpgate.wait(350);
    if (!failedSaves.length) return ui.notifications.info("Light spell resisted");
    let content = "";
    let optionUpdates = "";
    if (!type) {
        const typeOptions = [['none',{label:'None'}]]
                            .concat(Object.entries(CONFIG.Canvas.lightAnimations))
                            .reduce((acc, [a,b]) => acc += `<option id="type" value="${a}">${game.i18n.localize(b.label)}</option>`, ``);
        content += `<div class="form-group"><label>Light Animation Type</label><div class="form-fields"><select id="type">${typeOptions}</select></div></div> `;
    };
    if (!color) content += `<div class="form-group"><label for="color" style="line-height: 26px;">Color:</label><div class="form-fields"><input type="color" value="${game.user.color}" id="color"></div></div>`;
    if (!alpha) content += `<div class="form-group"><label for="alpha" style="line-height: 26px;">Color Intensity (Alpha):</label><div class="form-fields"><input type="range" value="0.25" id="alpha" min="0" max="1" step="0.05"><span class="range-value" id="alphaOutput">0.25</span></div><p class="hint">Configure the intensity of the light source.</p></div>`;
    if (!dim) content += `<div class="form-group"><label for="dim" style="line-height: 26px;">Dim (ft):</label><div class="form-fields"><input type="range" value="40" id="dim" min="0" max="120" step="5"><span class="range-value" id="dimOutput">20</span></div></div>`;
    if (!bright) content += `<div class="form-group"><label for="bright" style="line-height: 26px;">Bright (ft):</label><div class="form-fields"><input type="range" value="20" id="bright" min="0" max="120" step="5"><span class="range-value" id="brightOutput">20</span></div></div>`;
    if (!angle) content += `<div class="form-group"><label for="angle" style="line-height: 26px;">Emission Angle (Degrees):</label><div class="form-fields"><input type="range" value="360" id="angle" min="0" max="360" step="1"><span class="range-value" id="angleOutput">360</span></div><p class="hint">Configure the angle of the light source.</p></div>`;
    if (!intensity) content += `<div class="form-group"><label for="intensity" style="line-height: 26px;">Animation Intensity:</label><div class="form-fields"><input type="range" value="1" id="intensity" min="0" max="10" step="1"><span class="range-value" id="intensityOutput">1</span></div><p class="hint">Configure the intesity of the light source's animation.</p></div>`;
    if (!speed) content += `<div class="form-group"><label for="speed" style="line-height: 26px;">Animation Speed:</label><div class="form-fields"><input type="range" value="3" id="speed" min="0" max="10" step="1"><span class="range-value" id="speedOutput">3</span></div><p class="hint">Configure the speed of the light source's animation.</p></div>`;
    if (content) {
        optionUpdates = await Dialog.wait({
            title: "Light configuration",
            content: `<form>${content}</form>`,
            buttons: getLights(),
            close: () => {return false},
            render: () => {
                const valueAlpha = document.querySelector("#alphaOutput");
                const inputAlpha = document.querySelector("#alpha");
                if (valueAlpha && inputAlpha) {
                    valueAlpha.textContent = inputAlpha.value;
                    inputAlpha.addEventListener("input", (event) => {valueAlpha.textContent = event.target.value});
                }
                const valueDim = document.querySelector("#dimOutput");
                const inputDim = document.querySelector("#dim");
                if (valueDim && inputDim) {
                	valueDim.textContent = inputDim.value;
                	inputDim.addEventListener("input", (event) => {valueDim.textContent = event.target.value});
                }
                const valueBright = document.querySelector("#brightOutput");
                const inputBright = document.querySelector("#bright");
                if (valueBright && inputBright) {
                	valueBright.textContent = inputBright.value;
                	inputBright.addEventListener("input", (event) => {valueBright.textContent = event.target.value});
                }
                const valueAngle = document.querySelector("#angleOutput");
                const inputAngle = document.querySelector("#angle");
                if (valueAngle && inputAngle) {
                	valueAngle.textContent = inputAngle.value;
                	inputAngle.addEventListener("input", (event) => {valueAngle.textContent = event.target.value});
                }
                const valueSpeed = document.querySelector("#speedOutput");
                const inputSpeed = document.querySelector("#speed");
                if (valueSpeed && inputSpeed) {
                	valueSpeed.textContent = inputSpeed.value;
                	inputSpeed.addEventListener("input", (event) => {valueSpeed.textContent = event.target.value});
                }
                const valueIntensity = document.querySelector("#intensityOutput");
                const inputIntensity = document.querySelector("#intensity");
                if (valueIntensity && inputIntensity) {
                	valueIntensity.textContent = inputIntensity.value;
                	inputIntensity.addEventListener("input", (event) => {valueIntensity.textContent = event.target.value});
                }
            }
        })
    }
    let updates;
    if (!optionUpdates) {
        Hooks.once("midi-qol.preApplyDynamicEffects", workflow =>{return false})
        return ui.notifications.info("Light spell casting cancelled");
    }
    if (!!optionUpdates) updates = { token: { light: optionUpdates } };
    else updates = { token: { light: { color, alpha, dim, bright, angle, animation:{ speed, intensity, type } } } };
    const target = failedSaves[0]; //Token5e#Document
    if (_hasMutation(target,mutName)) {
        await MidiQOL.socket().executeAsGM("removeEffects", {actorUuid: target.uuid, effects:[getEffect(target.actor,"Light")?.id]});
        await warpgate.revert(target,mutName);
    }
    await warpgate.mutate(target,updates,{},{name:mutName});
    await DAE.setFlag(actor, "lightSRD", target.uuid);
}
if (args[0] === "off") {
    const sourceActor = fromUuidSync(lastArgValue.origin)?.actor;
    if (_hasMutation(token,mutName)) await warpgate.revert(token.document,mutName);
    await DAE.unsetFlag(sourceActor, "lightSRD");
}


function _hasMutation(token,mutName) {
    const tokenDoc = token instanceof TokenDocument ? token : token.document;
    const stack = warpgate.mutationStack(tokenDoc);
    return !!stack.getName(mutName);
}

function getLights() {
    let lightButtons = {};
    lightButtons = Object.assign(lightButtons, {
        apply: {
            label: `Apply`,
            icon: "<i class='fa-solid fa-lightbulb'></i>",
            callback: (html) => {
                const newColor = document.querySelector("#color")?.value ?? color;
                const newAlpha = document.querySelector("#alpha")?.value ?? alpha;
                const newDim = document.querySelector("#dim")?.value ?? dim;
                const newBright = document.querySelector("#bright")?.value ?? bright;
                const newAngle = document.querySelector("#angle")?.value ?? angle;
                const newType = document.querySelector("#type")?.value ?? type;
                const newIntensity = document.querySelector("#intensity")?.value ?? intensity;
                const newSpeed = document.querySelector("#speed")?.value ?? speed;
                return {color:newColor, alpha:newAlpha, dim:newDim, bright:newBright, angle:newAngle, animation:{type:newType, instensity:newIntensity, speed:newSpeed}};
            }
        }
    })
    return lightButtons;
}

function getEffect(actor, effectName) {
    let effect;
    if(isNewerVersion(game.version, 11)) effect = actor.effects.getName(effectName);
    else effect = actor.effects.find(e=>e.label === effectName);
    return effect;
}

data.command:
if (args[0] === "each") {

  const lastArg = args[args.length - 1];
  const effectData = {
    changes: [
      {
        key: "flags.midi-qol.grants.disadvantage.attack.all ",
        mode: CONST.ACTIVE_EFFECT_MODES.ADD,
        value: 1,
        priority: 20,
      },
    ],
    origin: lastArg.origin,
    disabled: false,
